package com.cleanyourtv.mobile.data

import android.content.Context
import com.cleanyourtv.mobile.safety.DebloatParser
import org.json.JSONObject

/**
 * The tested lists bundled from examples/. The catalog is generated by tools/bundle_lists.py and the
 * list text is copied unchanged, so the comments that say "keep this" stay with the list.
 */
class DeviceCatalog(private val context: Context) {

    val lists: List<TvList> by lazy { loadCatalog() }

    private val packageCache = HashMap<String, List<ListPackage>>()

    fun loadPackages(list: TvList): List<ListPackage> = synchronized(packageCache) {
        packageCache.getOrPut(list.id) {
            val text = context.assets.open("lists/${list.id}.txt")
                .bufferedReader(Charsets.UTF_8)
                .use { it.readText() }
            DebloatParser.parse(text)
        }
    }

    fun find(id: String): TvList? = lists.firstOrNull { it.id == id }

    fun listText(id: String): String =
        context.assets.open("lists/$id.txt").bufferedReader(Charsets.UTF_8).use { it.readText() }

    fun suggest(device: DeviceInfo, query: String = "", limit: Int = 8): List<TvList> {
        val queryTokens = normalize(query).split(' ').filter { it.isNotBlank() }
        val scored = lists.mapNotNull { list ->
            val haystack = haystack(list)
            if (queryTokens.isNotEmpty() && queryTokens.any { !haystack.contains(it) }) {
                null
            } else {
                val score = score(device, haystack) + if (queryTokens.isNotEmpty()) 1 else 0
                list to score
            }
        }
        return scored
            .filter { queryTokens.isNotEmpty() || it.second > 0 }
            .sortedWith(compareByDescending<Pair<TvList, Int>> { it.second }.thenBy { it.first.title })
            .take(limit)
            .map { it.first }
    }

    private fun score(device: DeviceInfo, haystack: String): Int {
        val flat = haystack.replace(" ", "")
        var score = 0
        val keys = listOf(
            device.device to 120,
            device.product to 110,
            device.model to 100,
            device.name to 90,
        )
        for ((value, weight) in keys) {
            val key = normalize(value).replace(" ", "")
            if (key.length >= 4 && flat.contains(key)) score += weight
        }
        val brand = normalize(device.brand.ifBlank { device.manufacturer })
        if (brand.length >= 3 && haystack.contains(brand)) score += 25
        val tokens = normalize(listOf(device.model, device.device, device.product).joinToString(" "))
            .split(' ')
            .filter { it.length >= 3 }
        score += tokens.count { haystack.contains(it) } * 6
        return score
    }

    private fun haystack(list: TvList): String = normalize(
        buildString {
            append(list.title).append(' ')
            append(list.id).append(' ')
            append(list.os).append(' ')
            append(list.header.joinToString(" ")).append(' ')
            append(list.notes)
        },
    )

    private fun normalize(value: String): String =
        value.lowercase().replace(Regex("[^\\p{L}\\p{N}]+"), " ").trim()

    private fun loadCatalog(): List<TvList> {
        val text = context.assets.open("catalog.json")
            .bufferedReader(Charsets.UTF_8)
            .use { it.readText() }
        val root = JSONObject(text)
        val array = root.optJSONArray("lists") ?: return emptyList()
        return buildList {
            for (index in 0 until array.length()) {
                val item = array.optJSONObject(index) ?: continue
                val id = item.optString("id").takeIf { it.isNotBlank() } ?: continue
                val header = item.optJSONArray("header")?.let { lines ->
                    (0 until lines.length()).map { lines.optString(it) }
                } ?: emptyList()
                add(
                    TvList(
                        id = id,
                        title = item.optString("title", id),
                        os = item.optString("os"),
                        notes = item.optString("notes"),
                        header = header,
                        packageCount = item.optInt("packageCount"),
                    ),
                )
            }
        }
    }
}
